SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `CATEGORIES`;
CREATE TABLE `CATEGORIES` (
  `Category_id` INT AUTO_INCREMENT,
  `Category_name` LONGTEXT,
  `Display_order` INT,
  `Is_active` INT,
  `Created_at` LONGTEXT,
  PRIMARY KEY (`Category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `MENU_ITEMS`;
CREATE TABLE `MENU_ITEMS` (
  `Item_id` INT AUTO_INCREMENT,
  `Category_id` INT,
  `Item_code` LONGTEXT,
  `Item_name` LONGTEXT,
  `Base_price` INT,
  `Cost_price` INT,
  `Image_url` LONGTEXT,
  `Description` LONGTEXT,
  `Is_available` INT,
  `Printer_target` LONGTEXT,
  `Created_at` LONGTEXT,
  `Toppings` LONGTEXT,
  PRIMARY KEY (`Item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `USERS`;
CREATE TABLE `USERS` (
  `User_id` INT AUTO_INCREMENT,
  `User_name` LONGTEXT,
  `User_password` LONGTEXT,
  `Role` LONGTEXT,
  `Created_at` VARCHAR(255),
  PRIMARY KEY (`User_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `ORDERS`;
CREATE TABLE `ORDERS` (
  `Order_id` INT AUTO_INCREMENT,
  `Order_code` LONGTEXT,
  `Order_type` LONGTEXT,
  `Table_number` LONGTEXT,
  `Customer_name` LONGTEXT,
  `Payment_method` LONGTEXT,
  `Final_amount` DOUBLE,
  `Note` LONGTEXT,
  `Created_at` VARCHAR(255),
  `Status` LONGTEXT,
  `Table_id` LONGTEXT,
  `Table_name` LONGTEXT,
  `Total_amount` DOUBLE,
  `Cancel_role` LONGTEXT,
  `Cancel_reason` LONGTEXT,
  `Is_edited` INT,
  `Payment_status` LONGTEXT,
  `Paid_by` LONGTEXT,
  `Paid_at` VARCHAR(255),
  `Staff_name` LONGTEXT,
  `Created_by` LONGTEXT,
  `Guest_count` INT,
  `Delivery_platform` LONGTEXT,
  `Customer_phone` LONGTEXT,
  `Delivery_address` LONGTEXT,
  `Shipping_fee` DOUBLE,
  `Payment_type` LONGTEXT,
  `Shipping_status` LONGTEXT,
  PRIMARY KEY (`Order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `ORDER_DETAILS`;
CREATE TABLE `ORDER_DETAILS` (
  `Detail_id` INT AUTO_INCREMENT,
  `Order_id` INT,
  `Item_name` LONGTEXT,
  `Quantity` INT,
  `Unit_price` DOUBLE,
  `Total_price` DOUBLE,
  `Note` LONGTEXT,
  `Toppings` LONGTEXT,
  PRIMARY KEY (`Detail_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `PAYMENT_METHODS`;
CREATE TABLE `PAYMENT_METHODS` (
  `Payment_id` INT AUTO_INCREMENT,
  `Payment_code` LONGTEXT,
  `Payment_name` LONGTEXT,
  `Guide_info` LONGTEXT,
  `Is_active` INT,
  PRIMARY KEY (`Payment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `ORDER_LOGS`;
CREATE TABLE `ORDER_LOGS` (
  `Log_id` INT AUTO_INCREMENT,
  `Order_code` LONGTEXT,
  `Modified_by` LONGTEXT,
  `Old_content` LONGTEXT,
  `New_content` LONGTEXT,
  `Modified_at` VARCHAR(255),
  PRIMARY KEY (`Log_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `STAFF_KPI_LOGS`;
CREATE TABLE `STAFF_KPI_LOGS` (
  `Log_id` INT AUTO_INCREMENT,
  `Staff_username` LONGTEXT,
  `Staff_name` LONGTEXT,
  `Staff_role` LONGTEXT,
  `Action_type` LONGTEXT,
  `Order_id` INT,
  `Order_code` LONGTEXT,
  `Table_number` LONGTEXT,
  `Amount` DOUBLE,
  `Item_count` INT,
  `Note` LONGTEXT,
  `Created_at` VARCHAR(255),
  PRIMARY KEY (`Log_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `SYSTEM_CONFIG`;
CREATE TABLE `SYSTEM_CONFIG` (
  `Key` VARCHAR(255),
  `Value` LONGTEXT,
  `Updated_at` VARCHAR(255),
  PRIMARY KEY (`Key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `DINING_TABLES`;
CREATE TABLE `DINING_TABLES` (
  `Table_id` INT AUTO_INCREMENT,
  `Table_code` LONGTEXT,
  `Table_name` LONGTEXT,
  `Area` LONGTEXT,
  `Capacity` INT,
  `Current_guests` INT,
  `Status` LONGTEXT,
  `Current_order_id` INT,
  `Current_order_code` LONGTEXT,
  `Current_amount` DOUBLE,
  `Payment_status` LONGTEXT,
  `Note` LONGTEXT,
  `Sort_order` INT,
  `Created_at` VARCHAR(255),
  `Updated_at` VARCHAR(255),
  PRIMARY KEY (`Table_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `GUEST_LOGS`;
CREATE TABLE `GUEST_LOGS` (
  `Log_id` INT AUTO_INCREMENT,
  `Table_id` INT,
  `Table_name` LONGTEXT,
  `Order_id` INT,
  `Order_code` LONGTEXT,
  `Guest_count` INT,
  `Action_type` LONGTEXT,
  `Staff_username` LONGTEXT,
  `Note` LONGTEXT,
  `Created_at` VARCHAR(255),
  PRIMARY KEY (`Log_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `DELIVERY_PLATFORMS`;
CREATE TABLE `DELIVERY_PLATFORMS` (
  `Platform_id` INT AUTO_INCREMENT,
  `Platform_name` LONGTEXT,
  `Platform_code` LONGTEXT,
  `Fee_percentage` DOUBLE,
  `Icon_class` LONGTEXT,
  `Color_code` LONGTEXT,
  `Is_active` INT,
  `Sort_order` INT,
  `Created_at` VARCHAR(255),
  PRIMARY KEY (`Platform_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `PROMOTION_BANNERS`;
CREATE TABLE `PROMOTION_BANNERS` (
  `Banner_id` INT AUTO_INCREMENT,
  `Title` LONGTEXT,
  `Subtitle` LONGTEXT,
  `Badge_text` LONGTEXT,
  `Price_text` LONGTEXT,
  `Image_url` LONGTEXT,
  `Sort_order` INT,
  `Is_active` INT,
  `Created_at` VARCHAR(255),
  PRIMARY KEY (`Banner_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


SET FOREIGN_KEY_CHECKS=1;
